 "content": "def transform(grid):
    """Extend the middle row and column of each solid 3x3 colored tile."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    tiles = []
    seen = set()
    for r in range(h - 2):
        for c in range(w - 2):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            if all(grid[rr][cc] == color for rr in range(r, r + 3) for cc in range(c, c + 3)):
                tiles.append((r + 1, c + 1, color))
                for rr in range(r, r + 3):
                    for cc in range(c, c + 3):
                        seen.add((rr, cc))
    centers = [(r, c, color) for r, c, color in tiles]
    for r, c, color in centers:
        # Each tile's two rays are interrupted only by lines belonging to
        # another tile; the tile's own center remains colored.
        for x in range(w):
            if x == c or not any(rr != r and cc == x for rr, cc, _ in centers):
                out[r][x] = color
        for y in range(h):
            if y == r or not any(cc != c and rr == y for rr, cc, _ in centers):
                out[y][c] = color
    return out

